import Testing
import Foundation
@testable import ReTiCA

// Cross-validation of LXMFAnnounceData.pack / .parse against genuine LXMF 1.1.0 wire bytes.
//
// Fixtures are generated by Tests/ReTiCATests/Vectors/generate_lxmf_announce_fixtures.py,
// which drives RNS.vendor.umsgpack.packb on the exact peer_data list that
// LXMRouter.get_announce_app_data (LXMRouter.py:1038-1049) constructs, then cross-checks
// every fixture against genuine LXMF.display_name_from_app_data / stamp_cost_from_app_data
// / compression_support_from_app_data.  See the generator for why msgpack.packb was used
// directly rather than driving get_announce_app_data itself.
//
// Every test asserts BOTH directions:
//   pack direction  — our LXMFAnnounceData.pack output is byte-identical to the fixture
//   parse direction — our LXMFAnnounceData.parse recovers the expected values from the fixture
//
// Test-honesty rule: every assertion is preceded by a non-nil / non-empty guard so that a
// nil/empty result causes an immediate failure, not a vacuous pass.

// MARK: — Fixture 1: name + cost

@Test func lxmfAnnounceDataCrossValidNameAndCost() throws {
    let f = try LXMFAnnounceFixtures.load()
    let fixture = f.nameCost

    // pack direction: our bytes must match the genuine wire format
    let ourPacked = LXMFAnnounceData.pack(displayName: fixture.displayName, stampCost: fixture.stampCost)
    #expect(!ourPacked.isEmpty)
    #expect(ourPacked == Data(hexString: fixture.packed)!)

    // parse direction: genuine wire bytes must yield the expected field values
    let parsed = LXMFAnnounceData.parse(Data(hexString: fixture.packed)!)
    #expect(parsed != nil)
    if let parsed {
        #expect(parsed.displayName == fixture.displayName)
        #expect(parsed.stampCost   == fixture.stampCost)
        #expect(parsed.supportsCompression == fixture.supportsCompression)
    }
}

// MARK: — Fixture 2: both nil

@Test func lxmfAnnounceDataCrossValidBothNil() throws {
    let f = try LXMFAnnounceFixtures.load()
    let fixture = f.bothNil

    // pack direction
    let ourPacked = LXMFAnnounceData.pack(displayName: nil, stampCost: nil)
    #expect(!ourPacked.isEmpty)
    #expect(ourPacked == Data(hexString: fixture.packed)!)

    // parse direction
    let parsed = LXMFAnnounceData.parse(Data(hexString: fixture.packed)!)
    #expect(parsed != nil)
    if let parsed {
        #expect(parsed.displayName == nil)
        #expect(parsed.stampCost   == nil)
        #expect(parsed.supportsCompression == fixture.supportsCompression)
    }
}

