// MARK: — Fixture 5: pre-0.5.0 raw-UTF-8 legacy blob

// The pack direction is intentionally absent for the legacy fixture: our pack always
// emits the 0.5.0+ msgpack format, which is correct — we never emit raw UTF-8.
// The legacy blob is a genuine LXMF-before-0.5.0 wire format that we must be able
// to PARSE but never emit; asserting byte-parity with a format we deliberately do not
// produce would be wrong.  The parse direction alone establishes the property we care about.
@Test func lxmfAnnounceDataCrossValidLegacyFormat() throws {
    let f = try LXMFAnnounceFixtures.load()
    let fixture = f.legacy

    let packedBytes = Data(hexString: fixture.packed)!
    #expect(!packedBytes.isEmpty)

    // parse direction: legacy raw-UTF-8 blob must be decoded as a display name
    let parsed = LXMFAnnounceData.parse(packedBytes)
    #expect(parsed != nil)
    if let parsed {
        #expect(parsed.displayName == fixture.displayName)  // "Legacy User"
        #expect(parsed.stampCost   == nil)
        #expect(parsed.supportsCompression == fixture.supportsCompression)  // true
    }
}
